CREATE OR REPLACE FUNCTION order_stage_transition_guard() RETURNS trigger AS $$
BEGIN
  -- The @stateMachine of Order.status (D117): an update that leaves the
  -- column's value is no move, and any other must be one the machine lists.
  IF NEW.stage IS NOT DISTINCT FROM OLD.stage THEN
    RETURN NEW;
  END IF;
  IF OLD.stage IN ('shipped') THEN
    RAISE EXCEPTION 'order.stage is terminal at %: it cannot move to %', OLD.stage, NEW.stage
      USING ERRCODE = 'check_violation';
  END IF;
  IF (OLD.stage IS NULL AND NEW.stage IN ('placed'))
    OR (OLD.stage = 'placed' AND NEW.stage IN ('shipped'))
  THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'order.stage cannot move from % to %', OLD.stage, NEW.stage
    USING ERRCODE = 'check_violation';
END;
$$ LANGUAGE plpgsql
